import{_ as a,o as t,c as o,a5 as s}from"./chunks/framework.C588jwcu.js";const u=JSON.parse('{"title":"シーン形式のリソース","description":"","frontmatter":{"title":"シーン形式のリソース","order":8},"headers":[],"relativePath":"ja/latest/tutorial/core/scene-assets.md","filePath":"ja/latest/tutorial/core/scene-assets.md","lastUpdated":1785683504000}'),c={name:"ja/latest/tutorial/core/scene-assets.md"};function r(d,e,n,_,i,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="シーン形式のリソース" tabindex="-1">シーン形式のリソース <a class="header-anchor" href="#シーン形式のリソース" aria-label="Permalink to &quot;シーン形式のリソース&quot;">​</a></h1><p>キャラクターと背景は <code>PackedScene</code> を参照します。シーンには画像、動画、Spine、Live2D、シェーダー、独自ノードを配置できます。</p><p>キャラクターシーンは <code>KND_CharacterSceneBase</code> を継承し、<code>_apply_status(resolved_status_name, original_status_name)</code> をオーバーライドします。システムは <code>apply_status(status_name)</code> を通じてこのメソッドを呼び出します。<code>actor change</code> はデフォルトでキャラクターマウントをフェードアウトし、状態を適用してからフェードインします。キャラクターシーンは複製されず、トランジションの完了後にストーリーを続行します。設定については<a href="./../script/actor/actor-change-state.html">アクター状態の切り替え</a>を参照してください。舞台アニメーションには、KS のモーション名と同名のアニメーションを持つ <code>KND_ActorMotionLayer</code> を使用します。</p><p>背景シーンは <code>KND_BackgroundSceneBase</code> を継承します。カメラ命令を使う場合は、一意な名前の <code>KonadoCamera2D</code> を追加してください。組み込みトランジションは <code>KND_BackgroundTransitionLayer</code> が処理します。</p>',4)])])}const m=a(c,[["render",r]]);export{u as __pageData,m as default};
